<body>
<div class="wrap">
  <h1>Budget Sketchbook</h1>
  <p class="hint">Set your monthly income, add what you spend by category, and watch a hand-drawn chart of your spending appear.</p>

  <section class="card" aria-labelledby="inc-h">
    <h2 id="inc-h">Monthly income</h2>
    <form id="income-form" class="income-row">
      <div class="field">
        <label for="income">Income amount</label>
        <input id="income" type="number" inputmode="decimal" step="any" min="0" placeholder="e.g. 3200">
      </div>
      <button type="submit">Save income</button>
    </form>
    <div class="summary">
      <div class="stat"><div class="k">Income</div><div class="v" id="s-income">—</div></div>
      <div class="stat"><div class="k">Spent</div><div class="v" id="s-spent">—</div></div>
      <div class="stat"><div class="k">Left over</div><div class="v accent" id="s-left">—</div></div>
    </div>
  </section>

  <section class="card" aria-labelledby="exp-h">
    <h2 id="exp-h">Add spending</h2>
    <form id="expense-form">
      <div class="add-row">
        <div>
          <label for="cat">Category</label>
          <select id="cat"></select>
        </div>
        <div>
          <label for="amt">Amount</label>
          <input id="amt" type="number" inputmode="decimal" step="any" min="0" placeholder="e.g. 45">
        </div>
        <button type="submit">Add</button>
      </div>
      <p class="err" id="err" role="alert"></p>
    </form>
    <ul class="list" id="list" aria-label="Spending entries"></ul>
    <p class="empty" id="empty">No spending yet. Add a category amount above to start sketching your budget.</p>
  </section>

  <section class="card" aria-labelledby="chart-h">
    <h2 id="chart-h">Spending by category</h2>
    <div id="chart"></div>
  </section>

  <div class="sr-only" aria-live="polite" id="live"></div>
</div>

<script>
(function(){
  const KEY = 'budget-tracker-v1';
  const CATEGORIES = ['Food','Rent','Transport','Utilities','Fun','Health','Shopping','Other'];
  const fmt = n => (Math.round(n*100)/100).toLocaleString('en-US');

  let state = { income:0, expenses:[] };

  const el = id => document.getElementById(id);
  const incomeForm = el('income-form'), incomeInput = el('income');
  const expForm = el('expense-form'), catSel = el('cat'), amtInput = el('amt'), errEl = el('err');
  const listEl = el('list'), emptyEl = el('empty'), chartEl = el('chart'), liveEl = el('live');

  CATEGORIES.forEach(c => { const o = document.createElement('option'); o.value=c; o.textContent=c; catSel.appendChild(o); });

  function announce(msg){ liveEl.textContent = msg; }

  function mulberry32(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; let t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
  function hash(s){ let h=2166136261; for(let i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,16777619);} return h>>>0; }

  function wobblyRect(x,y,w,h,rng){
    const pts=[]; const step=13;
    function edge(x1,y1,x2,y2){
      const len=Math.hypot(x2-x1,y2-y1); const n=Math.max(1,Math.round(len/step));
      for(let i=0;i<n;i++){ const t=i/n; pts.push([x1+(x2-x1)*t+(rng()-0.5)*2.4, y1+(y2-y1)*t+(rng()-0.5)*2.4]); }
    }
    edge(x,y,x+w,y); edge(x+w,y,x+w,y+h); edge(x+w,y+h,x,y+h); edge(x,y+h,x,y);
    pts.push(pts[0]);
    return 'M'+pts.map(p=>p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' L ');
  }

  function renderChart(){
    const totals = {};
    state.expenses.forEach(e => { totals[e.category]=(totals[e.category]||0)+e.amount; });
    const data = Object.entries(totals).filter(d=>d[1]>0).sort((a,b)=>b[1]-a[1]);
    if(!data.length){ chartEl.innerHTML = '<p class="empty">Add spending above to see your chart.</p>'; return; }
    const max = Math.max(...data.map(d=>d[1]));
    const W=340, left=104, right=18, barH=24, gap=14, top=14;
    const H = top + data.length*(barH+gap) + 12;
    const chartW = W - left - right;
    const svgNS='http://www.w3.org/2000/svg';
    const svg=document.createElementNS(svgNS,'svg');
    svg.setAttribute('viewBox',`0 0 ${W} ${H}`); svg.setAttribute('class','chart');
    svg.setAttribute('role','img'); svg.setAttribute('aria-label','Bar chart of spending by category');

    const axis=document.createElementNS(svgNS,'path');
    axis.setAttribute('d',`M${left} ${top-4} L${left} ${H-12}`); axis.setAttribute('class','axis');
    svg.appendChild(axis);

    data.forEach(([cat,val])=>{
      const i=data.indexOf([cat,val]);
      const y=top + data.findIndex(d=>d[0]===cat)*(barH+gap);
      const rng=mulberry32(hash(cat));
      const w=Math.max(3,(val/max)*chartW);
      const fill=document.createElementNS(svgNS,'path');
      fill.setAttribute('d',wobblyRect(left+1,y+2,w-1,barH-4,rng)); fill.setAttribute('class','bar');
      svg.appendChild(fill);
      const line=document.createElementNS(svgNS,'path');
      line.setAttribute('d',wobblyRect(left+1,y+2,w-1,barH-4, mulberry32(hash(cat)^0x9e3779b1))); line.setAttribute('class','bar-line');
      svg.appendChild(line);

      const lbl=document.createElementNS(svgNS,'text');
      lbl.setAttribute('x',left-8); lbl.setAttribute('y',y+barH/2+4); lbl.setAttribute('text-anchor','end');
      lbl.setAttribute('class','cat-lbl'); lbl.textContent=cat; svg.appendChild(lbl);

      const amt=document.createElementNS(svgNS,'text');
      amt.setAttribute('x',left+w+8); amt.setAttribute('y',y+barH/2+4); amt.setAttribute('class','amt-lbl');
      amt.textContent=fmt(val); svg.appendChild(amt);
    });
    chartEl.innerHTML=''; chartEl.appendChild(svg);
  }

  function renderList(){
    listEl.innerHTML='';
    if(!state.expenses.length){ emptyEl.style.display='block'; return; }
    emptyEl.style.display='none';
    state.expenses.forEach((e,i)=>{
      const li=document.createElement('li');
      const name=document.createElement('span'); name.className='cat-name'; name.textContent=e.category;
      const amt=document.createElement('span'); amt.className='cat-amt'; amt.textContent=fmt(e.amount);
      const rm=document.createElement('button'); rm.className='rm'; rm.type='button';
      rm.setAttribute('aria-label',`Remove ${e.category} ${fmt(e.amount)}`); rm.textContent='×';
      rm.addEventListener('click',()=>{ state.expenses.splice(i,1); save(); render(); announce(`Removed ${e.category}`); });
      li.append(name,amt,rm); listEl.appendChild(li);
    });
  }

  function render(){
    el('s-income').textContent = state.income ? fmt(state.income) : '—';
    const spent = state.expenses.reduce((s,e)=>s+e.amount,0);
    el('s-spent').textContent = fmt(spent);
    el('s-left').textContent = fmt(state.income - spent);
    renderList();
    renderChart();
  }

  function save(){ if(window.alfy && window.alfy.storage){ window.alfy.storage.set(KEY, state); } }

  incomeForm.addEventListener('submit', ev=>{
    ev.preventDefault();
    const v=parseFloat(incomeInput.value);
    if(isNaN(v)||v<0){ errEl.textContent=''; announce('Enter a valid income amount'); return; }
    state.income=v; errEl.textContent=''; save(); render(); announce(`Income set to ${fmt(v)}`);
  });

  expForm.addEventListener('submit', ev=>{
    ev.preventDefault();
    const v=parseFloat(amtInput.value);
    if(isNaN(v)||v<=0){ errEl.textContent='Enter an amount greater than zero.'; return; }
    errEl.textContent='';
    state.expenses.push({category:catSel.value, amount:v});
    amtInput.value=''; save(); render(); announce(`Added ${catSel.value} ${fmt(v)}`);
  });

  async function load(){
    try {
      if(window.alfy && window.alfy.storage){
        const saved = await window.alfy.storage.get(KEY);
        if(saved && typeof saved==='object'){
          state.income = typeof saved.income==='number' ? saved.income : 0;
          state.expenses = Array.isArray(saved.expenses) ? saved.expenses.filter(e=>e && e.category && typeof e.amount==='number') : [];
        }
      }
    } catch(e){}
    incomeInput.value = state.income || '';
    render();
  }
  load();
})();
</script>
</body>
</html>
